                        "qty", 1, "unitPrice", i.get("amount")));
            }
            BigDecimal amount = BigDecimal.ZERO;
            for (Map<String, Object> l : lineItems) {
                amount = amount.add(new BigDecimal(l.get("qty").toString())
                        .multiply(new BigDecimal(l.get("unitPrice").toString())));
